def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opps = []
    prev_bids = []
    dangerous_prev = []
    weak_opps = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                weak_opps += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 80:
                    dangerous_prev.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive_opps:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.75
    elif hp <= 4:
        urgency += 0.45
    elif hp <= 6:
        urgency += 0.2

    if no_water_days >= 2:
        urgency += 0.6
    elif no_water_days >= 1:
        urgency += 0.3

    urgency += 0.35 * scarcity

    endgame = day >= 8
    base = 18.0 + 20.0 * scarcity

    if avg_prev > 0:
        base = max(base, avg_prev * (0.52 + 0.18 * scarcity))

    target = base

    if hp <= 2 or no_water_days >= 2:
        target = max(target, highest_prev + 2.5, 92.0)
    elif scarcity >= 0.75 and dangerous_prev:
        target = max(target, highest_prev + 1.5)
    elif scarcity >= 0.45 and hp <= 5:
        target = max(target, avg_prev + 4.0)
    elif supply >= 22 and hp >= 7 and no_water_days == 0:
        target = min(target, 28.0)
    elif supply >= 20 and hp >= 6 and no_water_days == 0:
        target = min(target, 36.0)

    if weak_opps >= 2 and hp >= 6 and no_water_days == 0:
        target *= 0.88

    if endgame and hp <= 5:
        target = max(target, highest_prev + 2.0, 85.0)

    reserve_floor = 0.0
    days_left = max(0, 10 - day)
    if days_left >= 2 and hp >= 5:
        reserve_floor = 25.0
    if budget < reserve_floor:
        reserve_floor = 0.0

    target = min(target, budget - reserve_floor if budget > reserve_floor else budget)

    if target < 0:
        target = 0.0

    if budget <= 35:
        if hp <= 3 or no_water_days >= 1:
            target = min(budget, max(target, 30.0))
        else:
            target = min(budget, target)

    return float(max(0.0, min(budget, round(target, 2))))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    remaining_days = EPISODE_DAYS - current_day + 1

    critical_hp_threshold = 3
    critical_no_water_days_threshold = 1

    is_critical = (my_hp <= critical_hp_threshold) or (my_no_water_days >= critical_no_water_days_threshold)

    yesterday_bids = []
    total_opponent_water_req = 0
    for opp in alive_opponents:
        total_opponent_water_req += opp['water_requirement']
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    base_bid = DAILY_SALARY * 0.55

    if is_critical:
        aggressive_bid_factor = 0.95
        if my_hp <= 1:
            aggressive_bid_factor = 1.0
        base_bid = max(base_bid, DAILY_SALARY * aggressive_bid_factor)
    else:
        if my_hp > WATER_REQ * 2:
             base_bid = DAILY_SALARY * 0.4
        elif my_hp > WATER_REQ:
             base_bid = DAILY_SALARY * 0.5

    if yesterday_bids:
        max_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

        if is_critical:
            base_bid = max(base_bid, min(max_prev_bid + 5, DAILY_SALARY * 1.1))
        else:
            base_bid = max(base_bid, avg_prev_bid * 1.05)
            if my_hp > WATER_REQ * 2 and avg_prev_bid > DAILY_SALARY * 0.7:
                 base_bid = min(base_bid, avg_prev_bid * 0.9)

    total_demand_estimate = WATER_REQ + total_opponent_water_req
    if current_supply < total_demand_estimate * 0.75:
        base_bid *= 1.15
    elif current_supply < total_demand_estimate * 0.9:
        base_bid *= 1.05
    elif current_supply > total_demand_estimate * 1.5:
        base_bid *= 0.85
    elif current_supply > total_demand_estimate * 1.1:
        base_bid *= 0.95

    final_bid = min(my_budget, base_bid)
    final_bid = max(1.0, final_bid)

    return final_bid

